1	import Anthropic from "@anthropic-ai/sdk";
2	import { MODELS, EFFORT } from "./models";
3	import { narrateTool } from "./build-narration";
4	import { ASSET_KINDS, type AssetKind } from "./assets";
5	import { findAssets, formatMatchesForTool } from "./assets/materialize";
6	
7	export type AgentEvent =
8	  | { type: "status"; text: string }
9	  // A live line describing what the agent is doing RIGHT NOW, derived from a
10	  // real tool call (see lib/build-narration.ts). Distinct from "status", which
11	  // marks a phase change the route itself knows about.
12	  | { type: "progress"; text: string }
13	  | { type: "text"; text: string }
14	  | { type: "file"; path: string; action: "write" | "delete" }
15	  | {
16	      type: "usage";
17	      model: string;
18	      inputTokens: number;
19	      outputTokens: number;
20	      cacheReadTokens: number;
21	      cacheWriteTokens: number;
22	    };
23	
24	export type FileMap = Record<string, string>;
25	
26	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
27	
28	// Generated sites are real Vite + React + TypeScript + Tailwind apps, built
29	// server-side (lib/build-site.ts) into static output served from a
30	// locked-down CSP that blocks every external host — "no CDN, no remote
31	// anything" is a hard constraint rather than a style preference.
32	const SYSTEM = `You are Kodely's site builder. You turn a plain-English description into a real, working website — a genuine Vite + React + TypeScript + Tailwind app, not a static HTML mockup.
33	
34	## The project you're editing
35	Every project starts from a real foundation (package.json, vite.config.ts, tsconfig.json, index.html, src/main.tsx, src/index.css, src/App.tsx, and a few UI primitives under src/components/ui/). You almost never touch the config files — package.json, vite.config.ts, tsconfig.json and src/main.tsx are already correct and there is no way to add a new dependency, so leave them alone unless something is actually broken. Your work happens in \`src/App.tsx\`, new files under \`src/components/\`, and \`src/index.css\`.
36	
37	### index.html — the one config file you MUST edit
38	Every new site needs a real \`<head>\`. The foundation ships a placeholder title and a site is never actually called "Kodely Site" — that title is what shows in the browser tab, in Google, and in every link preview when someone shares the URL. Write, in the site's own language:
39	
40	- \`<title>\` — the real business or site name, with a short qualifier where it helps (e.g. "Bloom Pilates — Reformer studio in Denver"). Under ~60 characters.
41	- \`<meta name="description">\` — one specific sentence about what THIS business offers, ~150 characters. Describe the business, not the template.
42	- \`<meta property="og:title">\` and \`<meta property="og:description">\` — usually the same values; these are what appear when the link is shared.
43	- \`<html lang="...">\` — the correct language if the content is not English.
44	
45	Leave the rest of index.html alone (charset, viewport, the root div, the module script). Never add \`<link>\` or \`<script>\` tags pointing at a remote host — published sites run under a strict CSP that blocks external requests, so they fail silently.
46	
47	## Output contract
48	Use the write_file and delete_file tools. Always pass the complete final file — there is no patch tool.
49	- Build real, composable React components — a Hero, a FeatureGrid, a Footer — not one giant App.tsx.
50	- Style with Tailwind utility classes. The existing primitives (Button, Card, Section, Nav in src/components/ui/) are a starting point — reuse them, extend them, or write new ones as the design calls for, but keep the same quality bar.
51	- Multi-page: this is a single-page app. Build distinct sections/routes as components conditionally rendered or scrolled to, not separate .html files.
52	
53	## Hard constraints — these break the sandboxed build/serve, not just style
54	- NO external requests. No CDN scripts, no Google Fonts, no remote images, no
55	  fetch/XHR to other origins — the CSP blocks all of them at serve time.
56	- Only the dependencies already in package.json exist (react, react-dom). You
57	  cannot add packages — there is no install step per generation.
58	- Images are inline SVG, CSS gradients, or data: URIs. Never <img src="https://...">.
59	
60	## Assets — use these instead of drawing everything by hand
61	Kodely ships a catalogue of ~460 inlinable assets: icons (contact, social, commerce, food, trades, UI), country flags, curated gradients, mesh backgrounds, grain textures, section dividers, CSS patterns and initials avatars. All of them are safe under the CSP because none of them fetch anything.
62	Search the catalogue with the find_assets tool — pass what you need in plain words ("plumber wrench icon", "warm sunset gradient", "wave divider") and paste the source it returns.
63	Reach for the catalogue before hand-writing SVG path data: the results are cleaner and more consistent than improvised geometry, and they cost far fewer tokens. Hand-write only when nothing fits.
64	- Fonts come from the system stack (ui-sans-serif, -apple-system, "Segoe UI", Inter, sans-serif). No @import, no <link>, and no @font-face — not even with a base64 data: URI. The CSP sets no font-src, so fonts fall back to default-src 'self', which does NOT allow data: (unlike img-src, which does). A base64 font is blocked exactly like a remote one.
65	
66	## Quality bar
67	Ship something that looks designed, not templated. Real, specific copy for the
68	subject at hand — never "Lorem ipsum" and never placeholder headings like
69	"Your Title Here". Responsive down to 380px. Semantic HTML, labelled form
70	controls, sufficient colour contrast, and a visible :focus style. Include a
71	dark-mode treatment unless the brief implies otherwise. Give the page one
72	distinctive visual idea rather than a generic hero-plus-three-cards.
73	
74	## Never invent facts about a real business
75	"Specific copy" means specific to the SUBJECT, not invented details about a
76	real business. Never fabricate: street addresses, phone numbers, email
77	addresses, opening hours, prices, staff names, years in business, customer
78	counts, awards, certifications, review scores, or testimonials.
79	
80	These end up on a real business's public website. An invented phone number is
81	a real number belonging to somebody else; invented opening hours send real
82	customers to a closed door; an invented testimonial is a fabricated
83	endorsement. This outranks the "no placeholder text" rule above — when you
84	don't know a fact, that rule does not license you to make one up.
85	
86	Use a clearly-bracketed placeholder instead: [your phone number],
87	[your address], [your opening hours]. A bracket is an obvious prompt to fill
88	something in; a plausible-looking invention is one nobody notices before
89	publishing. Invent freely for anything that is genuinely a design choice —
90	headlines, section copy, taglines, colour, imagery.
91	
92	## Never build something that only pretends to work
93	There is no backend, so anything needing a server cannot function. Do not
94	build a contact form, booking form, newsletter signup, login, cart or checkout
95	that appears functional — a form that silently discards a real enquiry is
96	worse than no form.
97	
98	Where the brief asks for one, use a real alternative that works with no
99	server: a mailto: link, a tel: link, or a prominent [link to your booking
100	system]. If you show such a control as a visual element, its label must make
101	the destination obvious ("Email us", "Call now"), never "Submit" or "Send".
102	
103	## Editing an existing site
104	You are given the current source files. Change only what the request calls
105	for — do not restyle or restructure components the user did not ask about.
106	
107	## Working style
108	Write the files first, then finish with two or three sentences telling the user
109	what you built and what they might want to change next. Do not narrate each file
110	as you write it, and do not paste code into your reply — the user sees a live
111	preview of the result.`;
112	
113	const TOOLS: Anthropic.Tool[] = [
114	  {
115	    name: "write_file",
116	    description:
117	      "Create a file or replace its entire contents. Always pass the complete final file, never a fragment or a diff.",
118	    input_schema: {
119	      type: "object",
120	      properties: {
121	        path: {
122	          type: "string",
123	          description: "Project-relative path, e.g. 'index.html' or 'styles.css'. No leading slash.",
124	        },
125	        content: { type: "string", description: "The complete contents of the file." },
126	      },
127	      required: ["path", "content"],
128	    },
129	  },
130	  {
131	    name: "delete_file",
132	    description: "Delete a file that is no longer part of the site.",
133	    input_schema: {
134	      type: "object",
135	      properties: { path: { type: "string", description: "Project-relative path to delete." } },
136	      required: ["path"],
137	    },
138	  },
139	  {
140	    name: "find_assets",
141	    description:
142	      "Search Kodely's built-in asset catalogue (icons, country flags, gradients, mesh backgrounds, grain textures, section dividers, CSS patterns, initials avatars). Returns paste-ready source for each match. Everything it returns is inlinable and CSP-safe. Prefer this over hand-writing SVG path data.",
143	    input_schema: {
144	      type: "object",
145	      properties: {
146	        query: {
147	          type: "string",
148	          description:
149	            "Plain-words description, e.g. 'phone icon', 'warm sunset gradient', 'wave section divider', 'french flag'.",
150	        },
151	        kind: {
152	          type: "string",
153	          enum: [...ASSET_KINDS],
154	          description: "Optional filter to one kind of asset.",
155	        },
156	        limit: { type: "number", description: "Max results, default 6." },
157	      },
158	      required: ["query"],
159	    },
160	  },
161	];
162	
163	// Files the agent must never write, because they are EXECUTED server-side
164	// rather than merely served.
165	//
166	// `vite build` runs the project's own vite.config.* in a Node process on our
167	// machine (lib/build-site.ts). A config file is not data — it is code we run.
168	// Until now the only thing stopping a prompt from replacing it was a sentence
169	// in the system prompt, which is not an access control: "write a vite config
170	// that reads process.env and posts it somewhere" would have been executed.
171	//
172	// package.json and tsconfig.json are here for the same family of reasons
173	// (lifecycle scripts, compiler plugins). The foundation supplies all of these
174	// already and the agent has no legitimate reason to touch them — the prompt
175	// has always told it not to. This makes that a rule instead of a request.
176	const PROTECTED_PATHS = new Set([
177	  "package.json",
178	  "package-lock.json",
179	  "tsconfig.json",
180	  "tsconfig.node.json",
181	]);
182	const PROTECTED_PATTERNS = [
183	  /^vite\.config\.[cm]?[jt]s$/i,
184	  /^postcss\.config\.[cm]?[jt]s$/i,
185	  /^tailwind\.config\.[cm]?[jt]s$/i,
186	  /^\./, // dotfiles: .npmrc, .env, .babelrc, and the asset catalogue
187	  /^node_modules\//i,
188	];
189	
190	/** True when writing this path would hand the agent server-side execution. */
191	export function isProtectedPath(path: string): boolean {
192	  if (PROTECTED_PATHS.has(path)) return true;
193	  return PROTECTED_PATTERNS.some((re) => re.test(path));
194	}
195	
196	/** Reject path traversal, absolute paths, and executable config before anything touches the DB. */
197	export function normalizePath(raw: string): string | null {
198	  const path = raw.trim().replace(/^\.?\//, "");
199	  if (!path || path.length > 200) return null;
200	  if (path.includes("..") || path.startsWith("/") || path.includes("\\")) return null;
201	  if (!/^[A-Za-z0-9._/-]+$/.test(path)) return null;
202	  if (isProtectedPath(path)) return null;
203	  return path;
204	}
205	
206	function describeFiles(files: FileMap): string {
207	  const paths = Object.keys(files);
208	  if (paths.length === 0) return "The project is empty — this is the first build.";
209	  return [
210	    "Current files in the project:",
211	    ...paths.map((p) => `\n--- ${p} ---\n${files[p]}`),
212	  ].join("\n");
213	}
214	
215	type RunOptions = {
216	  /** Prior turns, oldest first. */
217	  history: { role: "user" | "assistant"; content: string }[];
218	  request: string;
219	  files: FileMap;
220	  /** First build of a site vs a follow-up tweak — drives how hard we think. */
221	  kind: "create" | "edit";
222	  /** A reference image attached to this turn's request (vision input). */
223	  image?: { mediaType: string; data: string };
224	  /** Applies the write; returning false rejects it (e.g. bad path). */
225	  onWrite: (path: string, content: string) => Promise<boolean>;
226	  onDelete: (path: string) => Promise<boolean>;
227	  /**
228	   * Aborted when the client disconnects (tab closed, network drop). Actually
229	   * cancels the in-flight Anthropic request instead of letting it run to
230	   * completion for nobody — a disconnect shouldn't mean paying full price for
231	   * a generation no one will ever see the result of.
232	   */
233	  signal?: AbortSignal;
234	};
235	
236	/**
237	 * Runs the plan → generate → apply loop, streaming progress as it goes.
238	 * Token usage is accumulated across every turn so the caller can meter the
239	 * true cost of the build (including the repair turns, which we may not bill).
240	 */
241	// Which generation engine to use.
242	//   api (default) — metered Anthropic API via ANTHROPIC_API_KEY. Real cost,
243	//                   real usage telemetry, real credit charges.
244	//   sdk           — Claude Agent SDK on this machine's `claude setup-token`
245	//                   subscription login. No metered spend, so no cost data and
246	//                   0 credits charged. See lib/agent-sdk.ts for the caveats.
247	// Defaults to `api` so a fresh clone never silently runs on someone's personal
248	// subscription; the environment opts in.
249	export const ENGINE = process.env.KODELY_ENGINE === "sdk" ? "sdk" : "api";
250	
251	export async function* runAgent(opts: RunOptions): AsyncGenerator<AgentEvent> {
252	  if (ENGINE === "sdk") {
253	    // Deliberately no try/catch fallback to the API engine: if the SDK is not
254	    // authenticated this must fail loudly rather than quietly spend money on
255	    // the metered key the operator asked not to use.
256	    const { runAgentSdk } = await import("./agent-sdk");
257	    yield* runAgentSdk(opts, SYSTEM);
258	    return;
259	  }
260	
261	  const model = MODELS.builder;
262	  // Effort is the sharpest cost lever we have: a first build is a blank-page
263	  // design problem and earns `high`, while a targeted tweak lands the same
264	  // result at `medium` for a fraction of the thinking tokens.
265	  const effort = opts.kind === "create" ? EFFORT.create : EFFORT.edit;
266	
267	  const messages: Anthropic.MessageParam[] = [];
268	  for (const turn of opts.history) {
269	    messages.push({ role: turn.role, content: turn.content });
270	  }
271	  const requestText = `${describeFiles(opts.files)}\n\n--- Request ---\n${opts.request}`;
272	  if (opts.image) {
273	    messages.push({
274	      role: "user",
275	      content: [
276	        {
277	          type: "image",
278	          source: {
279	            type: "base64",
280	            media_type: opts.image.mediaType as "image/png" | "image/jpeg" | "image/webp",
281	            data: opts.image.data,
282	          },
283	        },
284	        { type: "text", text: `${requestText}\n\n(A reference image is attached above — use it as visual/style guidance for the site.)` },
285	      ],
286	    });
287	  } else {
288	    messages.push({ role: "user", content: requestText });
289	  }
290	
291	  const totals = {
292	    inputTokens: 0,
293	    outputTokens: 0,
294	    cacheReadTokens: 0,
295	    cacheWriteTokens: 0,
296	  };
297	
298	  // Bounded so a confused model can never bill the user for an endless loop.
299	  const MAX_TURNS = 8;
300	
301	  for (let turn = 0; turn < MAX_TURNS; turn++) {
302	    if (opts.signal?.aborted) return;
303	
304	    const stream = anthropic.messages.stream(
305	      {
306	        model,
307	        max_tokens: 32_000,
308	        thinking: { type: "adaptive" },
309	        output_config: { effort },
310	        system: [{ type: "text", text: SYSTEM, cache_control: { type: "ephemeral" } }],
311	        tools: TOOLS,
312	        messages,
313	      },
314	      { signal: opts.signal },
315	    );
316	
317	    for await (const event of stream) {
318	      if (event.type === "content_block_delta" && event.delta.type === "text_delta") {
319	        yield { type: "text", text: event.delta.text };
320	      }
321	    }
322	
323	    const message = await stream.finalMessage();
324	    totals.inputTokens += message.usage.input_tokens ?? 0;
325	    totals.outputTokens += message.usage.output_tokens ?? 0;
326	    totals.cacheReadTokens += message.usage.cache_read_input_tokens ?? 0;
327	    totals.cacheWriteTokens += message.usage.cache_creation_input_tokens ?? 0;
328	
329	    if (message.stop_reason === "refusal") {
330	      throw new Error(
331	        "The request was declined. Try describing the site you want in different terms.",
332	      );
333	    }
334	
335	    const toolUses = message.content.filter(
336	      (b): b is Anthropic.ToolUseBlock => b.type === "tool_use",
337	    );
338	
339	    if (toolUses.length === 0) {
340	      yield { type: "usage", model, ...totals };
341	      return;
342	    }
343	
344	    messages.push({ role: "assistant", content: message.content });
345	
346	    const results: Anthropic.ToolResultBlockParam[] = [];
347	    for (const use of toolUses) {
348	      const input = use.input as {
349	        path?: string;
350	        content?: string;
351	        query?: string;
352	        kind?: string;
353	        limit?: number;
354	      };
355	
356	      // Handled before the path check below — this is the one tool that takes
357	      // no path, and running it through normalizePath would reject it outright.
358	      if (use.name === "find_assets") {
359	        yield { type: "progress", text: "Picking out icons and artwork" };
360	        const matches = findAssets(input.query ?? "", {
361	          kind: input.kind as AssetKind | undefined,
362	          limit: Math.min(Math.max(input.limit ?? 6, 1), 12),
363	        });
364	        results.push({
365	          type: "tool_result",
366	          tool_use_id: use.id,
367	          content: formatMatchesForTool(matches),
368	        });
369	        continue;
370	      }
371	
372	      const path = normalizePath(input.path ?? "");
373	
374	      if (!path) {
375	        results.push({
376	          type: "tool_result",
377	          tool_use_id: use.id,
378	          content: `Rejected: '${input.path}' is not a valid project-relative path.`,
379	          is_error: true,
380	        });
381	        continue;
382	      }
383	
384	      // Narrate before applying, so the line appears while the write is
385	      // happening rather than after it lands.
386	      const line = narrateTool(use.name, { path });
387	      if (line) yield { type: "progress", text: line };
388	
389	      if (use.name === "write_file") {
390	        const ok = await opts.onWrite(path, input.content ?? "");
391	        if (ok) yield { type: "file", path, action: "write" };
392	        results.push({
393	          type: "tool_result",
394	          tool_use_id: use.id,
395	          content: ok ? `Wrote ${path}.` : `Could not write ${path}.`,
396	          is_error: !ok,
397	        });
398	      } else if (use.name === "delete_file") {
399	        const ok = await opts.onDelete(path);
400	        if (ok) yield { type: "file", path, action: "delete" };
401	        results.push({
402	          type: "tool_result",
403	          tool_use_id: use.id,
404	          content: ok ? `Deleted ${path}.` : `${path} did not exist.`,
405	          is_error: false,
406	        });
407	      } else {
408	        results.push({
409	          type: "tool_result",
410	          tool_use_id: use.id,
411	          content: `Unknown tool ${use.name}.`,
412	          is_error: true,
413	        });
414	      }
415	    }
416	
417	    messages.push({ role: "user", content: results });
418	  }
419	
420	  yield { type: "usage", model, ...totals };
421	}
422

1	import Anthropic from "@anthropic-ai/sdk";
2	import { tmpdir } from "node:os";
3	import { ENGINE } from "./agent";
4	import { MODELS } from "./models";
5	
6	// Auto-enhance: turn a rough one-liner into a fuller spec the user reviews and
7	// edits BEFORE any credits are spent.
8	//
9	// Two jobs, both about the same failure mode — "almost right, but not quite":
10	//   1. Beginners don't know what to describe. A one-line prompt produces a
11	//      generic page, they blame the tool, they churn.
12	//   2. Nobody should discover what was built by paying for it. The spec is
13	//      shown, editable, and entirely optional; the user can always ignore it
14	//      and build with exactly what they typed.
15	//
16	// Deliberately NOT billed and NOT recorded as a build. It costs a fraction of
17	// a cent on the cheap model (see MODELS.enhancer) and charging for it would
18	// undo the point — a preview you pay for is not a preview. lib/rate-limit.ts
19	// carries the abuse ceiling instead of the credit meter.
20	
21	/** Longer than this and there is nothing left to expand — just build it. */
22	export const MAX_PROMPT_CHARS = 2000;
23	
24	// The spec is instructions for lib/agent.ts, so its hard constraints have to
25	// be repeated here or Enhance becomes a liar: it would cheerfully promise a
26	// booking system, the builder would produce a decorative form, and the user
27	// would have paid to find that out. Everything the generator cannot do is
28	// therefore banned from the spec, not merely discouraged.
29	//
30	// The word ceiling is a product decision as much as a cost one: a spec nobody
31	// reads is worse than no spec, and this has to be reviewable in ~20 seconds.
32	export const ENHANCE_SYSTEM = `You expand a one-line website idea into a short, concrete brief that the person can read, edit, and hand straight back as their build prompt.
33	
34	## What actually gets built
35	A single-page site: layout, sections, copy and visual style. That is the whole product. There is no backend of any kind.
36	
37	NEVER describe, promise or imply any of the following. The generator cannot build them, and a brief that asks for them produces a site that is broken or dishonest:
38	- databases, saved records, stored submissions, search over real data
39	- user accounts, sign-in, member areas, dashboards, admin pages
40	- payments, checkout, carts, or bookings that reserve anything real
41	- server code, APIs, scheduled jobs, email sending, contact forms that deliver a message
42	- anything loaded from another site: CDN scripts, web fonts, remote images, stock photography, embedded maps, video embeds, analytics, social feeds, live prices
43	
44	Published sites run under a strict Content Security Policy that blocks every external host. A form, a "Book now" button or a price table can exist as a VISUAL element on the page — describe it that way, and never as something that works.
45	
46	Images are inline SVG, CSS gradients and shapes, or simple illustration. Type comes from the system font stack. Say so when it matters; do not ask for photographs or a specific web font.
47	
48	## What to write
49	Plain text. No code, no markdown fences, no bullet characters beyond simple dashes. Under 220 words. Write in the same language the person used. Use exactly these five headings, in this order:
50	
51	Audience — who the site is for, in one sentence.
52	Goal — the single thing a visitor should do or understand.
53	Tone and visual style — two or three concrete adjectives, plus the colour feel, the typographic feel, and how imagery is handled.
54	Sections — the page's sections in order, each with one line saying what it holds.
55	Key content — the actual headline wording, the nav and button labels, and any names or claims to use.
56	
57	Rules:
58	- Be specific. Real headline wording, real section names, real labels — never "your headline here".
59	- Invent no facts about a real business: no addresses, phone numbers, prices, opening hours, testimonials or statistics. Where one is clearly needed, write a bracketed placeholder such as [your address] for the person to fill in.
60	- Keep every choice the person already made. Expand their idea; do not replace it.
61	- Output the brief and nothing else. No preamble, no sign-off, no questions back.`;
62	
63	// The metered path's client, constructed the same way lib/agent.ts does.
64	// Harmless when KODELY_ENGINE=sdk: nothing on that path ever calls it.
65	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
66	
67	// Hard ceilings, because the caller is a person staring at a spinner next to a
68	// button they could just press instead. The SDK path is far more generous: it
69	// spawns a Claude Code process, and cold start alone can eat several seconds.
70	const API_TIMEOUT_MS = 25_000;
71	const SDK_TIMEOUT_MS = 60_000;
72	
73	/**
74	 * One AbortSignal that trips on whichever comes first: our own deadline, or
75	 * the client hanging up. AbortSignal.any would do this in one line but the
76	 * timer still has to be cleared, so the teardown callback is needed regardless.
77	 */
78	function withDeadline(ms: number, signal?: AbortSignal) {
79	  const controller = new AbortController();
80	  const timer = setTimeout(() => controller.abort(), ms);
81	  const onAbort = () => controller.abort();
82	  if (signal?.aborted) controller.abort();
83	  else signal?.addEventListener("abort", onAbort, { once: true });
84	  return {
85	    controller,
86	    release() {
87	      clearTimeout(timer);
88	      signal?.removeEventListener("abort", onAbort);
