97	async function enhanceViaApi(prompt: string, signal?: AbortSignal): Promise<string> {
98	  const { controller, release } = withDeadline(API_TIMEOUT_MS, signal);
99	  try {
100	    // No `thinking` and no `output_config.effort` here on purpose: Haiku 4.5
101	    // rejects effort, and a 220-word brief is not a reasoning problem. If
102	    // KODELY_MODEL_ENHANCER is ever pointed at a bigger model, this stays
103	    // correct — it just leaves that model on its own defaults.
104	    const message = await anthropic.messages.create(
105	      {
106	        model: MODELS.enhancer,
107	        max_tokens: 1500,
108	        // No cache_control, unlike lib/agent.ts: this system prompt is well
109	        // under the ~1k-token minimum cacheable prefix, so a breakpoint here
110	        // would be silently ignored and only mislead the next reader.
111	        system: ENHANCE_SYSTEM,
112	        messages: [{ role: "user", content: userTurn(prompt) }],
113	      },
114	      { signal: controller.signal },
115	    );
116	
117	    if (message.stop_reason === "refusal") {
118	      throw new Error("The request was declined.");
119	    }
120	
121	    return message.content
122	      .filter((block): block is Anthropic.TextBlock => block.type === "text")
123	      .map((block) => block.text)
124	      .join("")
125	      .trim();
126	  } finally {
127	    release();
128	  }
129	}
