131	async function enhanceViaSdk(prompt: string, signal?: AbortSignal): Promise<string> {
132	  // Imported for its module-scope side effect as much as for query():
133	  // lib/agent-sdk.ts strips ANTHROPIC_API_KEY from the environment so nothing
134	  // the SDK spawns can quietly bill the metered key on a box whose operator
135	  // asked for the subscription engine. Enhance can be the first SDK call a
136	  // process makes, so it must not skip that.
137	  await import("./agent-sdk");
138	  const { query } = await import("@anthropic-ai/claude-agent-sdk");
139	
140	  const { controller, release } = withDeadline(SDK_TIMEOUT_MS, signal);
141	  let out = "";
142	  try {
143	    for await (const message of query({
144	      prompt: userTurn(prompt),
145	      options: {
146	        systemPrompt: ENHANCE_SYSTEM,
147	        model: MODELS.enhancer,
148	        // No tools at all — this is one prompt in, one paragraph out. Combined
149	        // with a temp cwd and no filesystem settings, the agent has nothing to
150	        // read: it cannot wander into this repo or pick up its CLAUDE.md.
151	        allowedTools: [],
152	        settingSources: [],
153	        cwd: tmpdir(),
154	        maxTurns: 1,
155	        permissionMode: "dontAsk",
156	        abortController: controller,
157	      },
158	    })) {
159	      if (message.type === "assistant" && message.message?.content) {
160	        for (const block of message.message.content) {
161	          if ("text" in block && block.text) out += block.text;
162	        }
163	      }
164	    }
165	  } finally {
166	    release();
167	  }
168	
169	  if (controller.signal.aborted) throw new Error("Enhance timed out.");
170	  return out.trim();
171	}
