42	// Downscale + re-encode client-side so a phone photo doesn't blow past
43	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
44	// at it) — a reference image only needs to be legible, not full-resolution.
45	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
46	  const bitmap = await createImageBitmap(file);
47	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
48	  const w = Math.round(bitmap.width * scale);
49	  const h = Math.round(bitmap.height * scale);
50	  const canvas = document.createElement("canvas");
51	  canvas.width = w;
52	  canvas.height = h;
53	  const ctx = canvas.getContext("2d");
54	  if (!ctx) throw new Error("canvas unsupported");
55	  ctx.drawImage(bitmap, 0, 0, w, h);
56	  return canvas.toDataURL("image/jpeg", quality);
57	}
