export type Column = { id: string; boardId: string; name: string; position: number };

export type CardType = "IDEA" | "FEATURE" | "BUG" | "CHORE";
export type CardPriority = "LOW" | "NORMAL" | "HIGH" | "URGENT";

export type Card = {
  id: string;
  columnId: string;
